    chart_h = height - top_margin - bottom_margin
    bar_h = max(12, min(24, (chart_h - 10) // len(items) - 4))
    spacing = (chart_h - bar_h * len(items)) / (len(items) + 1)

    svg_parts = [f'<svg viewBox="0 0 {width} {height}" xmlns="http://www.w3.org/2000/svg" style="max-width:{width}px;">']

    # Title
    if title:
        svg_parts.append(f'<text x="{width/2}" y="22" text-anchor="middle" font-size="14" font-weight="600" fill="#1e293b">{esc(title)}</text>')

    # Grid lines
    for i in range(5):
        x = left_margin + chart_w * i / 4
        val = max_val * i / 4
        svg_parts.append(f'<line x1="{x}" y1="{top_margin}" x2="{x}" y2="{top_margin + chart_h}" stroke="#e2e8f0" stroke-width="1"/>')
        svg_parts.append(f'<text x="{x}" y="{top_margin + chart_h + 8}" text-anchor="middle" font-size="10" fill="#94a3b8">{val:.0f}{value_suffix}</text>')

    for idx, (label, value) in enumerate(items):
        y = top_margin + spacing + idx * (bar_h + spacing)
        bar_w = (value / max_val) * chart_w

        # Label
        svg_parts.append(f'<text x="{left_margin - 8}" y="{y + bar_h/2 + 4}" text-anchor="end" font-size="11" fill="#475569">{esc(label[:30])}</text>')

        # Bar
        svg_parts.append(f'<rect x="{left_margin}" y="{y}" width="{bar_w}" height="{bar_h}" fill="{bar_color}" rx="3"/>')

        # Value label
        svg_parts.append(f'<text x="{left_margin + bar_w + 5}" y="{y + bar_h/2 + 4}" font-size="10" fill="#64748b">{value:.1f if isinstance(value, float) else int(value)}{value_suffix}</text>')

    svg_parts.append('</svg>')
    return '\n'.join(svg_parts)


def svg_line_chart(series_dict, width=700, height=320, colors=None, title='', y_label=''):
    """Generate an SVG line chart. series_dict = {name: [(x_label, value), ...], ...}"""
    if not series_dict:
        return '<p>No data</p>'

    if colors is None:
        colors = ['#2563eb', '#dc2626', '#16a34a', '#ca8a04', '#9333ea', '#0891b2', '#e11d48', '#65a30d']

    left_margin = 55
    right_margin = 20
    top_margin = 45
    bottom_margin = 55
    chart_w = width - left_margin - right_margin
    chart_h = height - top_margin - bottom_margin

    # Collect all points
    all_values = []
    all_labels = set()
    for name, points in series_dict.items():
        for label, val in points:
            all_values.append(val)
            all_labels.add(label)
    all_labels = sorted(all_labels)

    if not all_values:
        return '<p>No data</p>'

    min_val = min(all_values)
    max_val = max(all_values)
    if min_val == max_val:
        min_val = max_val - 1
        max_val = max_val + 1
    val_range = max_val - min_val

    # Only show every Nth label to avoid crowding
    n_labels = len(all_labels)
    label_step = max(1, n_labels // 12)

    svg_parts = [f'<svg viewBox="0 0 {width} {height}" xmlns="http://www.w3.org/2000/svg" style="max-width:{width}px;">']

    # Title
    if title:
        svg_parts.append(f'<text x="{width/2}" y="22" text-anchor="middle" font-size="14" font-weight="600" fill="#1e293b">{esc(title)}</text>')

    # Y-axis label
    if y_label:
        svg_parts.append(f'<text x="14" y="{top_margin + chart_h/2}" text-anchor="middle" font-size="11" fill="#64748b" transform="rotate(-90,14,{top_margin + chart_h/2})">{esc(y_label)}</text>')

    # Grid lines
    for i in range(5):
        y_pos = top_margin + chart_h - (chart_h * i / 4)
        val = min_val + val_range * i / 4
        svg_parts.append(f'<line x1="{left_margin}" y1="{y_pos}" x2="{left_margin + chart_w}" y2="{y_pos}" stroke="#e2e8f0" stroke-width="1"/>')
        svg_parts.append(f'<text x="{left_margin - 5}" y="{y_pos + 4}" text-anchor="end" font-size="10" fill="#94a3b8">{val:.0f}</text>')

    # X-axis labels
    for i, label in enumerate(all_labels):
        if i % label_step == 0 or i == n_labels - 1:
            x_pos = left_margin + (chart_w * i / max(1, n_labels - 1))
            # Rotate label for readability
            svg_parts.append(f'<text x="{x_pos}" y="{top_margin + chart_h + 15}" text-anchor="end" font-size="9" fill="#94a3b8" transform="rotate(-45,{x_pos},{top_margin + chart_h + 15})">{esc(label)}</text>')

    # Plot each series
    for s_idx, (name, points) in enumerate(series_dict.items()):
        color = colors[s_idx % len(colors)]
        points_dict = {label: val for label, val in points}

        path_parts = []
        for i, label in enumerate(all_labels):
            if label in points_dict:
                x_pos = left_margin + (chart_w * i / max(1, n_labels - 1))
                y_pos = top_margin + chart_h - ((points_dict[label] - min_val) / val_range * chart_h)
                if not path_parts:
                    path_parts.append(f'M {x_pos:.1f} {y_pos:.1f}')
                else:
                    path_parts.append(f'L {x_pos:.1f} {y_pos:.1f}')

        if path_parts:
            path_d = ' '.join(path_parts)
            svg_parts.append(f'<path d="{path_d}" fill="none" stroke="{color}" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/>')

            # Dots at data points
            for i, label in enumerate(all_labels):
                if label in points_dict:
                    x_pos = left_margin + (chart_w * i / max(1, n_labels - 1))
                    y_pos = top_margin + chart_h - ((points_dict[label] - min_val) / val_range * chart_h)
                    svg_parts.append(f'<circle cx="{x_pos:.1f}" cy="{y_pos:.1f}" r="3" fill="{color}"/>')

        # Legend entry
        legend_x = left_margin + s_idx * 130
        legend_y = height - 8
        svg_parts.append(f'<circle cx="{legend_x}" cy="{legend_y - 4}" r="4" fill="{color}"/>')
        svg_parts.append(f'<text x="{legend_x + 8}" y="{legend_y}" font-size="10" fill="#475569">{esc(name)}</text>')

    svg_parts.append('</svg>')
    return '\n'.join(svg_parts)


def svg_donut_chart(items, width=280, height=280, title=''):
    """Generate an SVG donut/pie chart. items = [(label, value, color), ...]"""
    if not items:
        return '<p>No data</p>'

    total = sum(v for _, v, _ in items)
    if total == 0:
        return '<p>No data</p>'

    cx, cy, r = width / 2, height / 2 + 10, min(width, height) / 2 - 40
    inner_r = r * 0.55

    svg_parts = [f'<svg viewBox="0 0 {width} {height + 80}" xmlns="http://www.w3.org/2000/svg" style="max-width:{width}px;">']

    if title:
        svg_parts.append(f'<text x="{width/2}" y="18" text-anchor="middle" font-size="13" font-weight="600" fill="#1e293b">{esc(title)}</text>')

    # Center text
    svg_parts.append(f'<text x="{cx}" y="{cy}" text-anchor="middle" font-size="22" font-weight="700" fill="#1e293b">{total:,}</text>')
    svg_parts.append(f'<text x="{cx}" y="{cy + 16}" text-anchor="middle" font-size="10" fill="#64748b">Total</text>')

    # Draw segments
    start_angle = -90
    for label, value, color in items:
        if value == 0:
            continue
        fraction = value / total
        end_angle = start_angle + fraction * 360

        # SVG arc
        x1 = cx + r * np_cos(np_radians(start_angle))
        y1 = cy + r * np_sin(np_radians(start_angle))
        x2 = cx + r * np_cos(np_radians(end_angle))
        y2 = cy + r * np_sin(np_radians(end_angle))
        ix1 = cx + inner_r * np_cos(np_radians(start_angle))
        iy1 = cy + inner_r * np_sin(np_radians(start_angle))
        ix2 = cx + inner_r * np_cos(np_radians(end_angle))
        iy2 = cy + inner_r * np_sin(np_radians(end_angle))

        large_arc = 1 if fraction > 0.5 else 0

        path = (f'M {x1:.1f} {y1:.1f} A {r} {r} 0 {large_arc} 1 {x2:.1f} {y2:.1f} '
                f'L {ix2:.1f} {iy2:.1f} A {inner_r} {inner_r} 0 {large_arc} 0 {ix1:.1f} {iy1:.1f} Z')

        svg_parts.append(f'<path d="{path}" fill="{color}" stroke="white" stroke-width="1.5"/>')
        start_angle = end_angle

    # Legend
    for i, (label, value, color) in enumerate(items):
        ly = height + 15 + i * 16
        lx = 10
        svg_parts.append(f'<rect x="{lx}" y="{ly}" width="10" height="10" fill="{color}" rx="2"/>')
        pct = value / total * 100
        svg_parts.append(f'<text x="{lx + 15}" y="{ly + 9}" font-size="10" fill="#475569">{esc(label)} ({pct:.1f}%)</text>')

    svg_parts.append('</svg>')
    return '\n'.join(svg_parts)


